const fs=require('node:fs'),assert=require('node:assert/strict'),{JSDOM}=require('jsdom');
(async()=>{const read=f=>fs.readFileSync('students/'+f,'utf8'),registry={};new Function('window',read('interactive-catalogue-20261030.js'))(registry);let tested=0,errors=[];
 for(const page of ['examples','explorers','labs','cargo','mollier','model-lab','advanced-lab']){const modules=registry.MT_INTERACTIVE_MODULES.filter(m=>m.url.split('#')[0]===page+'.html'),dom=new JSDOM(read(page+'.html'),{url:'https://example.test/students/'+modules[0].url,runScripts:'outside-only',pretendToBeVisual:true}),w=dom.window,d=w.document;w.addEventListener('error',e=>errors.push(page+': '+e.message));await new Promise(r=>w.addEventListener('load',r,{once:true}));for(const m of read(page+'.html').matchAll(/src="([^"?]+\.js)/g))w.eval(read(m[1]));const $=id=>d.getElementById(id),pause=()=>new Promise(r=>w.setTimeout(r,10));
  for(const mod of modules){const hash=mod.url.split('#')[1]||'';if(hash){w.location.hash=hash;await pause();}w.MT_LEARNING_CYCLE_UI.show();const initial=w.MT_LEARNING_CYCLE_UI.read();assert.equal(initial.id,mod.id);assert.ok(initial.metrics.length>0,mod.id);assert.ok(Number.isFinite(initial.question.expected),mod.id+' applied question');$('learning-cycle').open=true;await pause();assert.equal($('cycle-answer'),null,'Applied answer is not exposed before prediction');$('cycle-direction').value='higher';$('cycle-reason').value='Change one physical input';$('cycle-record').click();assert.equal(w.MT_LEARNING_CYCLE_UI.engine.state.stage,'change',mod.id);$('cycle-compare').click();assert.match(d.querySelector('.cycle-error').textContent,/Change at least/);
   const selector=mod.id==='truss'?'#experiment [name=E]':page==='mollier'?'#pressure-number':page==='cargo'?'#cargo-form input[name=displacement]':page==='labs'?(mod.id==='controls'?'#signal-form input:is([type=number],[data-mt-numeric])':'#'+mod.id+'-form input:is([type=number],[data-mt-numeric])'):'#experiment input:is([type=number],[data-mt-numeric])',input=d.querySelector(selector);assert.ok(input,mod.id+' input');const before=Number(input.value);input.value=String(before===0?1:before*1.01);input.dispatchEvent(new w.Event('input',{bubbles:true}));input.dispatchEvent(new w.Event('change',{bubbles:true}));await pause();const changed=w.MT_LEARNING_CYCLE_UI.read();assert.notEqual(changed.fingerprint,initial.fingerprint,mod.id+' actual changed state');$('cycle-compare').click();assert.equal(w.MT_LEARNING_CYCLE_UI.engine.state.stage,'compare',mod.id+' compared');assert.equal($('cycle-answer'),null);$('cycle-solve').click();assert.equal(w.MT_LEARNING_CYCLE_UI.engine.state.stage,'solve');assert.ok($('cycle-working').disabled);$('cycle-answer').value='invalid';$('cycle-check').click();assert.ok($('cycle-working').disabled);const q=w.MT_LEARNING_CYCLE_UI.engine.state.question;$('cycle-answer').value=String(q.expected);$('cycle-check').click();assert.equal(w.MT_LEARNING_CYCLE_UI.engine.state.solved,true,mod.id+' correct applied answer');$('cycle-working').click();assert.ok(!$('cycle-solution').hidden);assert.ok(JSON.parse(w.localStorage.getItem('mt-student-cycles-completed-v1')).includes(mod.id));tested++;
  }if(page==='model-lab'){w.location.hash='units';await pause();w.MT_LEARNING_CYCLE_UI.show();$('cycle-restart').click();const group=d.querySelector('[name=group]');group.value='temperature';group.dispatchEvent(new w.Event('input',{bubbles:true}));await pause();for(const option of [...$('cycle-metric').options]){$('cycle-metric').value=option.value;$('cycle-metric').dispatchEvent(new w.Event('change',{bubbles:true}));}assert.match($('cycle-baseline-preview').textContent,/Current result/);}
 await pause();dom.window.close();
 }
 assert.equal(tested,45);assert.deepEqual(errors,[]);console.log(JSON.stringify({status:'PASS',modules:tested,scope:'Actual seven module pages, every current/new context, prediction-first gating, real changes, before/after comparison, applied questions, invalid/valid answer gating, worked solutions and local completion.'}));
})().catch(e=>{console.error(e);process.exitCode=1;});
